import {monitorLinkKey,saveMonitorLink,readMonitorLink} from './monitor-links.js?v=all-network-20261016';
import {defaultUsernameField,trackingField,surveyUsers,surveyIssues,newSurveyIssues,loadSurveyRows,loadSurveyUsernames} from './survey-checks.js?v=all-network-20261016';
export function attachSurveyMonitor({state,$,makeTable,onSettingsChange=()=>{}}){
 let layers=[],account=null,timer=null,running=false,busy=false,previous=new Set(),generation=0;
 const message=(value,error=false)=>{$('monitor-status').textContent=value;$('monitor-status').classList.toggle('error',error);$('monitor-user-status').textContent=value;$('monitor-user-status').classList.toggle('error',error);};
 function stop(reason='Monitoring stopped.'){running=false;clearTimeout(timer);timer=null;message(reason);}
 function changed(){setTimeout(onSettingsChange,0);$('monitor-link-status').textContent='Selection changed. Save the monitoring link to keep these settings in this browser.';generation++;previous=new Set();stop('Settings changed. Run Check now or Start monitoring with your new selection.');$('monitor-summary').textContent='Previous results may be out of date. Run a new check.';}
 function auth(){if(!state.api||!state.user)throw Error('Sign in through Attribute Manager first.');if(Date.now()>=state.api.expires)throw Error('Session expired. Sign in again before monitoring.');return state.api;}
 async function action(task){if(busy||state.busy){message('Another operation is running. Try again when it finishes.',true);return;}busy=true;try{await task();}catch(error){stop(error.message);message(error.message,true);}finally{busy=false;}}
 const spaces=['Electric Device','Structure Junction','Electric Line'];
 function spaceFor(name){return spaces.find(space=>space.replace(/[^a-z]/gi,'').toLowerCase()===String(name).replace(/[^a-z]/gi,'').toLowerCase())||'Other layers';}
 function setupSpaces(){ $('monitor-layers').replaceChildren();for(const name of [...spaces,'Other layers']){const section=document.createElement('section');section.className='bulk-panel';const heading=document.createElement('h3');heading.textContent=name;section.append(heading);section.dataset.space=name;$('monitor-layers').append(section);}}
 const selectedLayers=()=>layers.filter(layer=>layer.check.checked);
 function selectedUsers(){return [...$('monitor-users').querySelectorAll('input:checked')].map(input=>input.value);}
 async function readLayer(layer,api,names){const missingIds=[];const rows=await loadSurveyRows(api,layer.url,layer.meta,names,(done,total)=>message('Reading '+layer.meta.name+': '+done+' readable / '+total+' listed records…'),id=>missingIds.push(id));return {rows,missingIds};}
 function assertCurrent(api,version){if(state.api!==api||generation!==version)throw Error('Session or monitor settings changed. Run a fresh check.');}
 async function loadLayers(){
  const api=auth();changed();const version=generation;const choices=[...$('layers').options].filter(option=>option.value);if(!choices.length)throw Error('Open a Feature Service in Attribute Manager first.');
  layers=[];account=api;setupSpaces();$('monitor-users').replaceChildren();$('monitor-results').replaceChildren();$('monitor-coverage').replaceChildren();
  for(const option of choices){assertCurrent(api,version);const box=document.createElement('details'),title=document.createElement('summary');title.textContent=option.text;box.open=true;box.append(title);[...$('monitor-layers').children].find(section=>section.dataset.space===spaceFor(option.text)).append(box);
   try{const meta=await api.request(option.value);meta.objectIdField||=meta.fields?.find(field=>field.type==='esriFieldTypeOID')?.name;if(!meta.fields?.length||!meta.objectIdField)throw Error('No supported field schema / object ID.');
    const check=document.createElement('input');check.type='checkbox';check.checked=spaceFor(option.text)!=='Other layers';check.setAttribute('aria-label','Monitor layer '+option.text);const label=document.createElement('label');label.className='null-toggle';label.append(check,document.createTextNode('Monitor every accessible record in this layer'));box.append(label);
    const source=document.createElement('select');source.setAttribute('aria-label',option.text+' username field');source.add(new Option('Choose the field containing surveyor usernames…',''));for(const field of meta.fields.filter(f=>f.type==='esriFieldTypeString'))source.add(new Option(field.name+' — '+(field.alias||field.name),field.name));const selectedSource=defaultUsernameField(meta,$('monitor-role').value);source.value=selectedSource;const sourceLabel=document.createElement('label');sourceLabel.textContent='Username values from this field (created_user in your example)';sourceLabel.append(source);box.append(sourceLabel);source.onchange=()=>{changed();$('monitor-users').replaceChildren();filterUsers();};
    const fields=[];for(const field of meta.fields){if(['esriFieldTypeOID','esriFieldTypeGlobalID','esriFieldTypeGeometry','esriFieldTypeBlob','esriFieldTypeRaster','esriFieldTypeXML'].includes(field.type)||Object.values(meta.editFieldsInfo||{}).includes(field.name))continue;const input=document.createElement('input');input.type='checkbox';input.value=field.name;input.setAttribute('aria-label',option.text+' required '+field.name);const row=document.createElement('label');row.className='null-toggle';row.append(input,document.createTextNode((field.alias||field.name)+' ['+field.name+']'));box.append(row);input.onchange=changed;fields.push(input);}
    const layer={url:option.value,meta,check,fields,source,space:spaceFor(option.text)};const spaceSelect=document.createElement('select');spaceSelect.setAttribute('aria-label',option.text+' monitoring space');for(const name of [...spaces,'Other layers'])spaceSelect.add(new Option(name,name));spaceSelect.value=layer.space;const spaceLabel=document.createElement('label');spaceLabel.textContent='Monitoring space';spaceLabel.append(spaceSelect);box.prepend(spaceLabel);spaceSelect.onchange=()=>{layer.space=spaceSelect.value;[...$('monitor-layers').children].find(section=>section.dataset.space===layer.space).append(box);changed();};const selectFields=document.createElement('button');selectFields.type='button';selectFields.textContent='Check all attributes in '+option.text;selectFields.onclick=()=>{fields.forEach(input=>input.checked=true);changed();};box.append(selectFields);check.onchange=()=>{changed();action(loadUsers);};layers.push(layer);const info=document.createElement('p');info.className='small';info.textContent='Creator: '+(meta.editFieldsInfo?.creatorField||'not exposed')+' · Last editor: '+(meta.editFieldsInfo?.editorField||'not exposed');box.append(info);
   }catch(error){const problem=document.createElement('p');problem.className='error';problem.textContent=error.message;box.append(problem);}
  }assertCurrent(api,version);message(layers.length+' accessible layer(s) loaded. Select every device and junction layer you need, then its required fields.');
 }
 $('monitor-load').onclick=()=>action(loadLayers);
 $('monitor-three').onclick=()=>action(async()=>{if(account!==auth()||!layers.length)await loadLayers();changed();for(const layer of layers)layer.check.checked=spaces.includes(layer.space);await loadUsers();const missing=spaces.filter(space=>!layers.some(layer=>layer.space===space));message(missing.length?'Some spaces are not linked: '+missing.join(', ')+'. Choose their actual layer under Other layers and set its Monitoring space, or open the correct service.':'All three network spaces selected. Choose required attributes in each, then Check now.',missing.length>0);$('monitor-three-status').textContent=missing.length?'Unavailable or unlinked: '+missing.join(', '):'All three spaces selected.';});
 $('monitor-all-users').onchange=()=>{changed();filterUsers();};
 async function loadUsers(){
  const api=auth();if(api!==account||!layers.length)await loadLayers();let selected=selectedLayers();if(!selected.length){const current=layers.find(layer=>layer.url===$('layers').value);if(!current)throw Error('Choose a layer in Attribute Manager, or check a monitor layer above, then click Load username values again.');current.check.checked=true;current.check.closest('details').open=true;selected=[current];}const version=generation;const role=$('monitor-role').value,users=new Set(),coverage=[],activity=new Map(),oldUsers=new Set(selectedUsers());
  for(const layer of selected){try{const source=trackingField(layer.meta,role,layer.source.value),result=await loadSurveyUsernames(api,layer.url,layer.meta,source,(done,total)=>message('Reading '+layer.meta.name+': '+done+' / '+total+' records…'));assertCurrent(api,version);for(const user of result.users){users.add(user);const info=activity.get(user)||{layers:new Set()};info.layers.add(layer.meta.name+' ['+source+']');activity.set(user,info);}coverage.push([layer.meta.name+' ['+source+']',result.recordCount===null?result.users.length+' distinct usernames':result.recordCount+' records',result.method+(result.complete?' — values query complete.':' — PARTIAL: '+result.missingIds.length+' inaccessible/removed ID(s), examples: '+result.missingIds.slice(0,8).join(', '))]);}catch(error){assertCurrent(api,version);coverage.push([layer.meta.name,'Not covered',error.message]);}}
  assertCurrent(api,version);$('monitor-users').replaceChildren();for(const user of [...users].sort()){const info=activity.get(user);addUser(user,[...info.layers].join(', '),oldUsers.has(user));}
  $('monitor-coverage').replaceChildren(makeTable(['Layer','Accessible records','Coverage notes'],coverage));$('monitor-user-coverage').replaceChildren(makeTable(['Layer / source field','Values read','Load result'],coverage));filterUsers();const failed=coverage.filter(row=>row[1]==='Not covered'||String(row[2]).includes('PARTIAL:')).length;message(users.size+' username value(s) loaded from readable records. '+(failed?failed+' layer(s) have incomplete coverage — see Load result below.':'Select the username checkboxes below.'),!!failed);
 }
 $('monitor-users-load').onclick=()=>action(loadUsers);
 document.getElementById('survey-tab').addEventListener('click',()=>{if(state.api&&state.user)action(loadUsers);else message('Sign in and open a Feature Service in Attribute Manager to load the surveyor list.',true);});
 $('monitor-user-select-visible').onclick=()=>{changed();for(const label of $('monitor-users').children)if(!label.hidden)label.querySelector('input').checked=true;filterUsers();};
 $('monitor-user-clear').onclick=()=>{changed();for(const input of $('monitor-users').querySelectorAll('input'))input.checked=false;filterUsers();};
 function addUser(user,detail,checked=false){const input=document.createElement('input');input.type='checkbox';input.value=user;input.checked=checked;input.setAttribute('aria-label','Watch username '+user);input.onchange=()=>{changed();filterUsers();};const label=document.createElement('label');label.className='null-toggle';label.dataset.username=user.toLowerCase();label.append(input,document.createTextNode(user+' — '+detail));$('monitor-users').append(label);}

 async function check(){
  const api=auth(),version=generation;if(api!==account)throw Error('Load monitor layers again for this sign-in.');const selected=selectedLayers(),users=$('monitor-all-users').checked?null:selectedUsers(),role=$('monitor-role').value;if(!selected.length||(users!==null&&!users.length))throw Error('Select layers and at least one username.');if(selected.some(layer=>!layer.fields.some(input=>input.checked)))throw Error('Choose the attributes to check in: '+selected.filter(layer=>!layer.fields.some(input=>input.checked)).map(layer=>layer.meta.name).join(', ')+'. Use Check all attributes in each space if every field must be filled.');
  const issues=[],coverage=[];let complete=true,recordCount=0;
  for(const layer of selected){try{trackingField(layer.meta,role,layer.source.value);const {rows,missingIds}=await readLayer(layer,api,[layer.source.value,...layer.fields.filter(input=>input.checked).map(input=>input.value),...(layer.meta.globalIdField?[layer.meta.globalIdField]:layer.meta.fields.filter(f=>f.type==='esriFieldTypeGlobalID').map(f=>f.name))]);assertCurrent(api,version);issues.push(...surveyIssues(layer.url,layer.meta,rows,role,users,layer.fields.filter(input=>input.checked).map(input=>input.value),layer.source.value));recordCount+=rows.length;const unknown=rows.filter(row=>!row.attributes[trackingField(layer.meta,role,layer.source.value)]).length;coverage.push([layer.meta.name,rows.length,(unknown?'Incomplete attribution: '+unknown+' record(s) without username. ':'')+(missingIds.length?'PARTIAL: '+missingIds.length+' inaccessible/removed record(s); examples: '+missingIds.slice(0,8).join(', '):'All listed rows read')]);if(unknown||missingIds.length)complete=false;}catch(error){assertCurrent(api,version);complete=false;coverage.push([layer.meta.name,'Not checked',error.message]);}}
  assertCurrent(api,version);const fresh=newSurveyIssues(issues,previous);if(complete)previous=new Set(issues.map(issue=>issue.key));else issues.forEach(issue=>previous.add(issue.key));
  $('monitor-results').replaceChildren();for(const space of [...spaces,'Other layers']){const group=selected.filter(layer=>layer.space===space),urls=new Set(group.map(layer=>layer.url)),items=issues.filter(issue=>urls.has(issue.url)),section=document.createElement('section'),heading=document.createElement('h3'),status=document.createElement('p');section.className='bulk-panel';heading.textContent=space;status.textContent=group.length?items.length+' missing required value(s) across '+group.length+' selected layer(s). See coverage below for read failures and incomplete scans.':(layers.some(layer=>layer.space===space)?'Not included in this check. Use Select all three network layers above.':'No accessible layer linked to this space. Open the correct service, or assign its actual layer using Monitoring space in section 1.');section.append(heading,status);if(items.length)section.append(makeTable(['Layer','Tracking username','Global ID / Object ID','Required field','Missing value'],items.slice(0,1000).map(issue=>[issue.layer,issue.user,issue.id,issue.field,issue.kind])));if(items.length>1000){const limit=document.createElement('p');limit.textContent='Showing the first 1,000 issues in this space.';section.append(limit);}if(group.length)section.append(makeTable(['Layer','Accessible records','Coverage notes'],coverage.filter(row=>group.some(layer=>layer.meta.name===row[0]))));$('monitor-results').append(section);}$('monitor-coverage').replaceChildren(makeTable(['Layer','Accessible records','Coverage notes'],coverage));
  const summary=issues.length+' missing required value(s); '+fresh.length+' new issue(s). '+recordCount+' accessible record(s) read across '+selected.length+' selected layer(s). '+(complete?'Scan complete for accessible records.':'Coverage incomplete — review problems below.')+(issues.length>1000?' Showing up to 1,000 issues per space.':'');$('monitor-summary').textContent=summary;message('Last check: '+new Date().toLocaleString('en-GB',{timeZone:'Africa/Kigali'})+' (Kigali)'+'. '+(running?'Monitoring continues while this app is open.':'Manual check finished.'));
  if(fresh.length&&typeof Notification!=='undefined'&&Notification.permission==='granted')new Notification('REG Survey Quality Monitor',{body:fresh.length+' new missing required attribute issue(s) for selected usernames. Open the app for details.'});
 }
 $('monitor-check').onclick=()=>action(check);
 async function tick(){if(!running)return;if(busy||state.busy){timer=setTimeout(tick,5000);return;}await action(check);if(running)timer=setTimeout(tick,Number($('monitor-interval').value));}
 $('monitor-start').onclick=()=>{if(busy||state.busy){message('Wait for the current operation to finish.',true);return;}clearTimeout(timer);running=true;tick();};
 $('monitor-stop').onclick=()=>stop();
 $('monitor-role').onchange=()=>{changed();for(const layer of layers)layer.source.value=defaultUsernameField(layer.meta,$('monitor-role').value);$('monitor-users').replaceChildren();filterUsers();};$('monitor-interval').onchange=changed;
 function filterUsers(){const term=$('monitor-user-search').value.trim().toLowerCase();let shown=0;for(const label of $('monitor-users').children){label.hidden=!label.dataset.username.includes(term);if(!label.hidden)shown++;}$('monitor-user-matches').textContent=shown+' / '+$('monitor-users').children.length+' usernames shown; '+selectedUsers().length+' selected.'+($('monitor-all-users').checked?' All usernames mode includes future usernames and records with no tracking username.':'')+(shown===0?' Clear the search or load username values from the correct field.':' Select the checkboxes below to monitor these users.');}
 $('monitor-user-search').oninput=filterUsers;
 function linkKey(){auth();return monitorLinkKey(state.api.portal,state.user.username);}
 $('monitor-link-form').onsubmit=e=>{e.preventDefault();action(async()=>{const chosen=selectedLayers(),users=selectedUsers();if(!chosen.length||(!$('monitor-all-users').checked&&!users.length))throw Error('Select layers and at least one username before saving a link.');const link={allUsers:$('monitor-all-users').checked,version:1,name:$('monitor-link-name').value.trim()||'My survey monitoring',role:$('monitor-role').value,interval:Number($('monitor-interval').value),users,layers:chosen.map(layer=>({url:layer.url,source:trackingField(layer.meta,$('monitor-role').value,layer.source.value),required:layer.fields.filter(input=>input.checked).map(input=>input.value),space:layer.space}))};saveMonitorLink(localStorage,linkKey(),link);$('monitor-link-status').textContent='Saved “'+link.name+'”: '+(link.allUsers?'all usernames (including future usernames)':link.users.length+' username(s)')+', '+link.layers.length+' layer(s). Stored only for this portal account in this browser. '+(link.layers.some(layer=>!layer.required.length)?'Required-field rules are still needed before monitoring.':'Use Start monitoring when ready.');message('Monitoring link saved. Saving does not start background checks.');});};
 async function restoreLink(link){const options=new Set([...$('layers').options].map(option=>option.value));if(link.layers.some(layer=>!options.has(layer.url)))throw Error('Open the saved Feature Service in Attribute Manager first. This link does not grant access to another service.');$('monitor-role').value=link.role;$('monitor-all-users').checked=link.allUsers===true;await loadLayers();for(const layer of layers)layer.check.checked=false;for(const saved of link.layers){const layer=layers.find(item=>item.url===saved.url);if(!layer||!layer.meta.fields.some(field=>field.name===saved.source&&field.type==='esriFieldTypeString')||saved.required.some(name=>!layer.fields.some(input=>input.value===name)))throw Error('A saved layer or field is unavailable. Review the service schema and save an updated link.');layer.check.checked=true;if(spaces.includes(saved.space)||saved.space==='Other layers'){layer.space=saved.space;layer.check.closest('details').querySelector('select').value=saved.space;[...$('monitor-layers').children].find(section=>section.dataset.space===saved.space).append(layer.check.closest('details'));}layer.source.value=saved.source;layer.check.closest('details').open=true;layer.fields.forEach(input=>input.checked=saved.required.includes(input.value));}$('monitor-interval').value=String(link.interval);$('monitor-link-name').value=link.name;await loadUsers();const found=new Set([...$('monitor-users').querySelectorAll('input')].map(input=>input.value));for(const user of link.users)if(!found.has(user))addUser(user,'Saved selection — not found in this readable snapshot',true);for(const input of $('monitor-users').querySelectorAll('input'))input.checked=link.users.includes(input.value);filterUsers();$('monitor-link-status').textContent='Restored “'+link.name+'”. Review coverage and required fields, then Start monitoring. No checks were started automatically.';}
 $('monitor-link-restore').onclick=()=>action(()=>restoreLink(readMonitorLink(localStorage,linkKey())));

 $('monitor-notifications').onclick=async()=>{if(typeof Notification==='undefined'){message('Desktop notifications are unavailable in this browser. In-app alerts remain available.',true);return;}const permission=await Notification.requestPermission();message(permission==='granted'?'Desktop notifications enabled. Select usernames and start monitoring.':'Desktop notifications were not enabled. In-app alerts remain available.');};
 window.addEventListener('pagehide',()=>stop());
 return {async selectLayers(urls){const oldUsers=new Set(selectedUsers()),oldLayers=new Map(layers.map(layer=>[layer.url,{source:layer.source.value,required:layer.fields.filter(input=>input.checked).map(input=>input.value),space:layer.space}]));await loadLayers();for(const layer of layers){layer.check.checked=urls.includes(layer.url);const prior=oldLayers.get(layer.url);if(prior){if([...layer.source.options].some(option=>option.value===prior.source))layer.source.value=prior.source;layer.fields.forEach(input=>input.checked=prior.required.includes(input.value));layer.space=prior.space;layer.check.closest('details').querySelector('select').value=prior.space;[...$('monitor-layers').children].find(section=>section.dataset.space===prior.space).append(layer.check.closest('details'));}}const unavailable=urls.filter(url=>!layers.some(layer=>layer.url===url));if(unavailable.length)throw Error('Some selected layers could not be loaded. Review the layer problems.');await loadUsers();for(const input of $('monitor-users').querySelectorAll('input'))input.checked=oldUsers.has(input.value);filterUsers();},snapshot(){const chosen=selectedLayers();return {allUsers:$('monitor-all-users').checked,version:1,name:$('monitor-link-name').value,role:$('monitor-role').value,interval:Number($('monitor-interval').value),users:selectedUsers(),layers:chosen.map(layer=>({url:layer.url,source:layer.source.value,required:layer.fields.filter(input=>input.checked).map(input=>input.value),space:layer.space}))};},restore:restoreLink,reset(){stop('New query. Choose layers, required attributes and usernames.');generation++;previous=new Set();layers=[];account=null;for(const id of ['monitor-layers','monitor-users','monitor-results','monitor-coverage','monitor-user-coverage'])$(id).replaceChildren();$('monitor-summary').textContent='';$('monitor-user-search').value='';$('monitor-all-users').checked=false;$('monitor-role').value='creator';$('monitor-interval').value='300000';$('monitor-link-name').value='My survey monitoring';}};

}
